with enriched as (select id, event_time, ntile(10) over (partition by page, session_id order by duration_sec desc, id) as duration_sec_bucket, count(duration_sec) over (partition by session_id) as session_id_count_duration_sec, max(duration_sec) over (partition by event_type order by cast(event_time as bigint) range between 2592000 preceding and current row) as duration_sec_max_30d from web_events where event_type = 'add_to_cart'), filtered as (select id, event_time, session_id_count_duration_sec, duration_sec_max_30d, date_format(event_time, 'yyyy-MM-dd') as event_time_label, round(session_id_count_duration_sec, 2) as session_id_count_duration_sec_rounded from enriched where event_time >= timestamp '2023-05-25 22:00:00' and session_id_count_duration_sec >= 8), with_windows as (select *, lag(duration_sec_max_30d, 2, 0) over (order by duration_sec_max_30d, id) as prev_duration_sec_max_30d, cume_dist() over (order by duration_sec_max_30d desc nulls first) as duration_sec_max_30d_cume_dist from filtered), cleaned as (select *, greatest(duration_sec_max_30d, session_id_count_duration_sec_rounded) as greatest_duration_sec_max_30d_session_id_count_duration_sec_rounded from with_windows where session_id_count_duration_sec >= 9), metrics as (select *, min(duration_sec_max_30d) over (order by event_time, id rows between unbounded preceding and current row) as running_min_duration_sec_max_30d, avg(duration_sec_max_30d) over (order by event_time, id rows between unbounded preceding and current row) as running_avg_duration_sec_max_30d, count(duration_sec_max_30d) over (order by event_time, id rows between unbounded preceding and current row) as running_count_duration_sec_max_30d from cleaned), scored as (select *, avg(duration_sec_max_30d_cume_dist) over (order by duration_sec_max_30d_cume_dist, id rows between 3 preceding and current row) as duration_sec_max_30d_cume_dist_avg_3, lead(running_count_duration_sec_max_30d, 1) over (order by greatest_duration_sec_max_30d_session_id_count_duration_sec_rounded, id) as next_running_count_duration_sec_max_30d, sum(prev_duration_sec_max_30d) over (order by session_id_count_duration_sec, id rows between unbounded preceding and current row) as cumulative_prev_duration_sec_max_30d, avg(session_id_count_duration_sec_rounded) over (order by prev_duration_sec_max_30d, id rows between 2 preceding and current row) as session_id_count_duration_sec_rounded_avg_2 from metrics), with_windows_web_events as (select id, event_time, session_id_count_duration_sec, duration_sec_max_30d, session_id_count_duration_sec_rounded, duration_sec_max_30d_cume_dist, running_min_duration_sec_max_30d, duration_sec_max_30d_cume_dist_avg_3, next_running_count_duration_sec_max_30d, session_id_count_duration_sec_rounded_avg_2, row_number() over (order by event_time, id) as event_seq, sum(session_id_count_duration_sec_rounded_avg_2) over (order by cast(event_time as bigint) range between 604800 preceding and current row) as session_id_count_duration_sec_rounded_avg_2_sum_7d from scored) select case when session_id_count_duration_sec_rounded_avg_2_sum_7d >= 382 then 'LARGE' else 'SMALL' end as session_id_count_duration_sec_rounded_avg_2_sum_7d_tier, case when running_min_duration_sec_max_30d >= 370 then 'HIGH' else 'LOW' end as running_min_duration_sec_max_30d_tier, round(avg(duration_sec_max_30d_cume_dist), 2) as avg_duration_sec_max_30d_cume_dist, min(event_time) as first_seen from with_windows_web_events group by case when session_id_count_duration_sec_rounded_avg_2_sum_7d >= 382 then 'LARGE' else 'SMALL' end, case when running_min_duration_sec_max_30d >= 370 then 'HIGH' else 'LOW' end;
